n41717.content:
\begin{definition}\label{def:class-number-hplus}
  \lean{KummerCriterion.hPlus}\leanok
  \uses{def:cm-real-subfield, def:class-number-h}
For a CM field $K$, the plus class number is the class number of the
maximal real subfield:
\[
  h^+(K)=h(K^+).
\]
\end{definition}

n41718.content:
\begin{theorem}\label{thm:map-comap-ring-of-integers}
  \lean{KummerCriterion.map_comap_eq_ringOfIntegers}\leanok
  \uses{def:cm-real-subfield}
If $J$ is an ideal of $\mathcal O_{L^+}$, then extension to $\mathcal O_L$
followed by contraction is the identity:
\[
  (J\mathcal O_L)\cap\mathcal O_{L^+}=J.
\]
\end{theorem}

n41720.content:
\begin{theorem}\label{thm:is-principal-map-span-singleton}
  \lean{KummerCriterion.isPrincipal_of_map_eq_span_singleton_of_mem}\leanok
  \uses{thm:map-comap-ring-of-integers}
Let $I$ be an ideal of $\mathcal O_{K^+}$.  If $I\mathcal O_K$ is generated
by the image of an element $b_0\in\mathcal O_{K^+}$, then $I$ is principal,
generated by $b_0$.
\end{theorem}

n41722.content:
\begin{theorem}\label{thm:ideal-map-conj}
  \lean{KummerCriterion.ideal_map_conj_eq}\leanok
  \uses{def:cm-real-subfield}
If $I$ is an ideal of $\mathcal O_{K^+}$, then the extended ideal
$I\mathcal O_K$ is fixed by complex conjugation.
\end{theorem}

n41724.content:
\begin{theorem}\label{thm:conj-generator-associated}
  \lean{KummerCriterion.conj_generator_associated}\leanok
  \uses{thm:ideal-map-conj}
Suppose $I \ne 0$ and $I\mathcal O_K=(a)$.  Then, by
\cref{thm:ideal-map-conj}, also $I\mathcal O_K=(\overline a)$, and the two
generators are associated: there is a unit $u\in\mathcal O_K^\times$ with
\[
  \overline a = u a.
\]
\end{theorem}

n41726.content:
\begin{theorem}\label{thm:conj-unit-mul-one}
  \lean{KummerCriterion.conj_unit_mul_eq_one}\leanok
  \uses{thm:conj-generator-associated}
The unit $u$ obtained from $\overline a=ua$ in
\cref{thm:conj-generator-associated} satisfies
\[
  u\overline u=1.
\]
\end{theorem}

n41728.content:
\begin{theorem}\label{thm:antisymmetric-unit-classification}
  \lean{KummerCriterion.antisymmetric_unit_eq_neg_one_pow_mul_zeta_pow}\leanok
  \uses{thm:conj-unit-mul-one}
Let $K$ be the $p$th cyclotomic field with $p$ odd.  If
$u\in\mathcal O_K^\times$ satisfies $u\overline u=1$, then
\[
  u=(-1)^n\zeta_p^m
\]
for some integers $n,m$.
\end{theorem}

n41732.content:
\begin{theorem}\label{thm:mem-ring-of-integers-conj-self}
  \lean{KummerCriterion.mem_ringOfIntegers_of_conj_eq_self}\leanok
  \uses{def:cm-real-subfield}
If $b\in\mathcal O_K$ is fixed by complex conjugation, then it is the image
of an element of $\mathcal O_{K^+}$.
\end{theorem}

n41734.content:
\begin{theorem}\label{thm:is-principal-after-extension}
  \lean{KummerCriterion.isPrincipal_of_isPrincipal_map_Kplus}\leanok
  \uses{thm:is-principal-map-span-singleton, thm:ideal-map-conj,
  thm:conj-generator-associated, thm:conj-unit-mul-one,
  thm:antisymmetric-unit-classification, thm:conj-fixed-associate,
  thm:mem-ring-of-integers-conj-self}
Let $K$ be the $p$th cyclotomic field, with $p$ odd.  If an ideal of
$\mathcal O_{K^+}$ becomes principal after extension to $\mathcal O_K$,
then it was already principal.
\end{theorem}

n41736.content:
\begin{definition}\label{def:class-group-map}
  \lean{KummerCriterion.classGroupMap}\leanok
  \uses{def:cm-real-subfield}
The inclusion $\mathcal O_{K^+}\subseteq\mathcal O_K$ induces, by extension
of fractional ideals, the class-group homomorphism
\[
  \mathrm{Cl}(\mathcal O_{K^+})\longrightarrow \mathrm{Cl}(\mathcal O_K).
\]
\end{definition}

n41737.content:
\begin{theorem}\label{thm:class-group-map-injective}
  \lean{KummerCriterion.classGroupMap_injective}\leanok
  \uses{def:class-group-map, thm:is-principal-after-extension}
For an odd prime cyclotomic field, the map
\[
  \mathrm{Cl}(\mathcal O_{K^+})\longrightarrow \mathrm{Cl}(\mathcal O_K)
\]
is injective.
\end{theorem}

n41739.content:
\begin{theorem}\label{thm:hplus-divides-h}
  \lean{KummerCriterion.hPlus_dvd_h}\leanok
  \uses{def:class-number-h, def:class-number-hplus,
  thm:class-group-map-injective}
The plus class number divides the full class number:
\[
  h^+(K)\mid h(K).
\]
\end{theorem}

n41741.content:
\begin{definition}\label{def:class-number-hminus}
  \lean{KummerCriterion.hMinus}\leanok
  \uses{thm:hplus-divides-h}
The relative class number is the natural-number quotient
\[
  h^-(K)=h(K)/h^+(K),
\]
which is well defined by \cref{thm:hplus-divides-h}.
\end{definition}

n41742.content:
\begin{theorem}\label{thm:h-factorisation}
  \lean{KummerCriterion.h_eq_hPlus_mul_hMinus}\leanok
  \uses{def:class-number-hminus, thm:hplus-divides-h}
The class number factors as
\[
  h(K)=h^+(K)\,h^-(K).
\]
\end{theorem}

n41749.content:
\begin{theorem}\label{thm:bernoulli-padicInt-below}
  \lean{KummerCriterion.bernoulli_mem_padicInt_of_lt_sub_one}\leanok
For $0<n<p-1$, the classical Bernoulli number $B_n$ is $p$-adically
integral: $B_n \in \mathbb{Z}_p$.
\end{theorem}

n41751.content:
\begin{theorem}\label{thm:bernoulli-den-coprime}
  \lean{KummerCriterion.prime_not_dvd_bernoulli_den_of_lt_sub_one}\leanok
  \uses{thm:bernoulli-padicInt-below}
For $0<n<p-1$, the prime $p$ does not divide the denominator of $B_n$.
\end{theorem}

n41753.content:
\begin{lemma}\label{lem:padic-bernoulli-factor}
  \lean{KummerCriterion.exists_padicInt_bernoulli_factor}\leanok
  \uses{thm:bernoulli-den-coprime}
For $0<n<p-1$, the quotient $B_n/n$ lies in $\mathbb{Z}_p$, and it is a $p$-adic
unit if and only if $p$ does not divide the numerator of $B_n$.
\end{lemma}

n41755.content:
\begin{theorem}\label{thm:teichmuller-bernoulli-congruence}
  \lean{KummerCriterion.bernoulliGen_teichmuller_pow_sModEq_div}\leanok
  \uses{def:generalized-bernoulli, def:teichmuller}
For the odd exponents $j$ occurring in the relative class-number formula
(odd $j$ with $j + 1$ divisible by neither $p$ nor $p-1$),
\[
  B_{1,\omega^j}
  \equiv \frac{B_{j+1}}{j+1}\pmod p .
\]
\end{theorem}

n41757.content:
\begin{theorem}\label{thm:hplus-even-lvalues}
  \lean{KummerCriterion.hPlus_formula_of_evenLValues}\leanok
  \uses{def:dirichlet-character, def:class-number-hplus}
The plus class number is given by the even part of the cyclotomic
$L$-value product:
\[
  h^+(K)=
  c_{K^+}
  \prod_{\substack{\chi\ \mathrm{even}\\ \chi\ne1}}
  \left(
    -\,\tau(\chi^{-1})^{-1}
    \sum_{a \bmod p} \chi^{-1}(a)\,
      \log\bigl|1-e^{2\pi i a/p}\bigr|
  \right),
\]
where each factor of the product equals $L(1,\chi)$ and $c_{K^+}$ is the
explicit constant of the analytic class-number formula of $K^+$ (built
from the discriminant, the regulator and the roots of unity of $K^+$).
\end{theorem}

n41759.content:
\begin{theorem}\label{thm:raw-gauss-product}
  \lean{KummerCriterion.rawGaussProduct}\leanok
  \uses{def:dirichlet-character}
The product of the Gauss sums over the odd characters modulo $p$ is
\[
  \prod_{\chi\ \mathrm{odd}} \tau(\chi)
  \;=\;
  i^{\,(p-1)/2}\,\sqrt{p^{\,(p-1)/2}} .
\]
\end{theorem}

n41761.content:
\begin{theorem}\label{thm:cyclotomic-gauss-goal}
  \lean{KummerCriterion.cyclotomicHGaussGoal_holds}\leanok
  \uses{thm:raw-gauss-product}
The explicit Gauss-product evaluation of \cref{thm:raw-gauss-product}
satisfies the packaged Gauss hypothesis required by the relative
class-number assembly theorem (\cref{thm:hminus-formula-from-inputs}).
\end{theorem}

n41765.content:
\begin{theorem}\label{thm:hminus-formula}
  \lean{KummerCriterion.hMinus_formula}\leanok
  \uses{thm:hminus-formula-from-inputs, thm:hplus-even-lvalues,
  thm:cyclotomic-gauss-goal}
For an odd prime cyclotomic field,
\[
  h^-(K)
  =
  2p\prod_{\chi\ \mathrm{odd}}
    \left(-\frac12 B_{1,\chi^{-1}}\right).
\]
\end{theorem}

n41767.content:
\begin{theorem}\label{thm:hminus-teichmuller-mod-p}
  \lean{KummerCriterion.hMinus_formula_teichmuller_mod_p}\leanok
  \uses{thm:hminus-formula, def:teichmuller}
There exists $z\in\mathbb{Z}_p$ such that, inside $\mathbb{Q}_p$,
\[
  h^-(K)
  =
  \prod_{\substack{j<p-2\\ j\ \mathrm{odd}}}
    \left(-\frac12 B_{1,\omega^j}\right)
  + pz .
\]
\end{theorem}

n41769.content:
\begin{theorem}\label{thm:hminus-bernoulli-mod-p}
  \lean{KummerCriterion.hMinus_formula_bernoulli_mod_p}\leanok
  \uses{thm:hminus-teichmuller-mod-p, thm:teichmuller-bernoulli-congruence,
  lem:padic-bernoulli-factor}
There exists $z\in\mathbb{Z}_p$ such that, inside $\mathbb{Q}_p$,
\[
  h^-(K)
  =
  \prod_{\substack{j<p-2\\ j\ \mathrm{odd}}}
    \left(-\frac12\,\frac{B_{j+1}}{j+1}\right)
  + pz .
\]
\end{theorem}

n41775.content:
\begin{theorem}\label{thm:hminus-nondiv-to-bernoulli-nondiv}
  \lean{KummerCriterion.bernoulli_nonzero_of_not_dvd_hMinus}\leanok
  \uses{thm:hminus-bernoulli-final}
If $p\nmid h^-(K)$, then for every $k$ with $1\le k$ and $2k\le p-3$,
\[
  p\nmid\operatorname{num}(B_{2k}).
\]
\end{theorem}

n41778.content:
\begin{definition}\label{def:CPlus-generator}
  \lean{KummerCriterion.CPlusGenerator}\leanok
  \uses{def:real-cyclotomic-unit}
The \emph{standard generators} are the $(p-3)/2$ real cyclotomic units
\[
  \varepsilon_2,\ \varepsilon_3,\ \ldots,\ \varepsilon_{(p-1)/2}
\]
of \cref{def:real-cyclotomic-unit}, indexed in the formalisation by
$i \in \{0, \ldots, (p-5)/2\}$ via $a = i + 2$.
\end{definition}

n41779.content:
\begin{definition}\label{def:CPlus}
  \lean{KummerCriterion.CPlus}\leanok
  \uses{def:CPlus-generator}
The subgroup $C^+\subseteq(\mathcal O_{K^+})^\times$ is generated by $-1$
and the standard real cyclotomic units:
\[
  C^+=\bigl\langle -1,\ \varepsilon_2,\ldots,\varepsilon_{(p-1)/2}
  \bigr\rangle.
\]
\end{definition}

n41781.content:
\begin{theorem}\label{thm:normalized-square}
  \lean{KummerCriterion.normalizedCPlusGenerator_sq_eq_CPlusGenerator}\leanok
  \uses{def:CPlus, def:normalizedCPlus}
Each normalised generator squares to the corresponding standard generator:
\[
  \xi_a^{\,2} = \varepsilon_a
  \qquad (2 \le a \le (p-1)/2).
\]
\end{theorem}

n41782.content:
\begin{proof}\leanok
Using the identity $1-\zeta_p^{-a} = -\zeta_p^{-a}(1-\zeta_p^a)$ in the
numerator and denominator of $\varepsilon_a$,
\[
  \varepsilon_a
  = \frac{(1-\zeta_p^a)\cdot\bigl(-\zeta_p^{-a}\bigr)(1-\zeta_p^a)}{(1-\zeta_p)\cdot\bigl(-\zeta_p^{-1}\bigr)(1-\zeta_p)}
  = \zeta_p^{\,1-a}\,\frac{(1-\zeta_p^a)^2}{(1-\zeta_p)^2}
  = \xi_a^{\,2}.
\]
\end{proof}

n41783.content:
\begin{theorem}\label{thm:CPlus-normalized-index}
  \lean{KummerCriterion.CPlus_index_prime_dvd_iff_normalizedCPlus_index_prime_dvd}\leanok
  \uses{thm:normalized-square}
For an odd prime $p$,
\[
  p\mid[(\mathcal O_{K^+})^\times:C^+]
  \Longleftrightarrow
  p\mid[(\mathcal O_{K^+})^\times:C^+_{\mathrm{norm}}].
\]
\end{theorem}

n41786.content:
\begin{definition}\label{def:pPowerSubgroup}
  \lean{KummerCriterion.pPowerSubgroup}\leanok
For a subgroup $H$ of an abelian group, $H^p$ denotes the exact image of
the $p$th-power map:
\[
  H^p=\{h^p:h\in H\}
\]
(an actual image, not the subgroup generated by it; for abelian groups the
two coincide).
\end{definition}

n41787.content:
\begin{definition}\label{def:pSaturated}
  \lean{KummerCriterion.pSaturated}\leanok
  \uses{def:pPowerSubgroup}
A subgroup $H\le E$ is \emph{$p$-saturated} in $E$ when
\[
  H\cap E^p\subseteq H^p,
\]
that is, when every element of $H$ that is a $p$th power in $E$ is already
the $p$th power of an element of $H$.
\end{definition}

n41788.content:
\begin{definition}\label{def:CPlusExponentProduct}
  \lean{KummerCriterion.CPlusExponentProduct}\leanok
  \uses{def:CPlus}
An \emph{exponent product} is an expression
\[
  (-1)^s\prod_{a=2}^{(p-1)/2}\varepsilon_a^{\,e_a}
\]
with integer exponents $s, e_a \in \mathbb{Z}$, packaged together with the element
of $C^+$ it represents.
\end{definition}

n41789.content:
\begin{theorem}\label{thm:exists-CPlusExponentProduct}
  \lean{KummerCriterion.exists_CPlusExponentProduct_of_mem_CPlus}\leanok
  \uses{def:CPlusExponentProduct}
Every element of $C^+$ admits an exponent-product expression.
\end{theorem}

n41791.content:
\begin{theorem}\label{thm:CPlus-pSaturated-exponents}
  \lean{KummerCriterion.CPlus_pSaturated_of_generator_exponents_modP_zero}\leanok
  \uses{def:pSaturated, thm:exists-CPlusExponentProduct}
Assume that whenever an exponent product
\[
  (-1)^s\prod_a\varepsilon_a^{\,e_a}
\]
is a $p$th power in $E^+$, every exponent $e_a$ is divisible by $p$.  Then
$C^+$ is $p$-saturated in $E^+$.
\end{theorem}

n41793.content:
\begin{theorem}\label{thm:not-dvd-index-of-pSaturated}
  \lean{KummerCriterion.not_dvd_index_of_pSaturated}\leanok
  \uses{def:pSaturated, def:CPlus, def:EPlus}
If $C^+$ is $p$-saturated in $E^+$, then
\[
  p\nmid[E^+:C^+].
\]
\end{theorem}

n41796.content:
\begin{definition}\label{def:concreteKummerLogMatrix}
  \lean{KummerCriterion.CyclotomicUnits.concreteKummerLogMatrix}\leanok
  \uses{def:kummerLogRank, def:CPlus-generator}
The \emph{Kummer logarithm matrix} $M$ is the $r \times r$ matrix over
$\mathbb{F}_p$ whose $a$th column consists of the coordinates, in the Dwork basis
of the relevant fixed subalgebra, of the completed $p$-adic logarithm of
the generator $\varepsilon_a$, reduced modulo $p$.
\end{definition}

n41799.content:
\begin{theorem}\label{thm:vandermonde-nonzero}
  \lean{KummerCriterion.CyclotomicUnits.vandermonde_teichmuller_even_sub_one_det_ne_zero}\leanok
The Teichm\"uller Vandermonde determinant occurring in
\cref{thm:kummer-log-vandermonde} is nonzero.
\end{theorem}

n41801.content:
\begin{theorem}\label{thm:kummer-det-bernoulli-factor}
  \lean{KummerCriterion.CyclotomicUnits.concreteKummerLogMatrix_det_ne_zero_iff_forall_bernoulliFactor_ne_zero}\leanok
  \uses{thm:kummer-log-vandermonde, thm:vandermonde-nonzero}
$\det M \ne 0$ if and only if every diagonal Bernoulli factor is nonzero.
